⣿⣿"
local function countTools()
    local total = 0
    for _, container in ipairs({backpack, player.Character}) do
        if container then
            for _, item in ipairs(container:GetChildren()) do
                if item:IsA("Tool") then total += 1 end
            end
        end
    end
    return total
end
-- Start equip cycling independently, so new tools can be equipped immediately.
_G.StopImageToolLoops = false
task.spawn(function()
    while not _G.StopImageToolLoops do
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.Health > 0 then
            local tools = {}
            for _, container in ipairs({backpack, character}) do
                for _, child in ipairs(container:GetChildren()) do
                    if child:IsA("Tool") then table.insert(tools, child) end
                end
            end
            for _, tool in ipairs(tools) do
                if _G.StopImageToolLoops then break end
                if tool.Parent == backpack then
                    humanoid:EquipTool(tool)
                end
                task.wait(0.001)
            end
        end
        task.wait(0.001)
    end
end)
-- InvokeServer yields; requests are sequential, not instantaneous.
local requested = 0
local maxRequests = math.max(0, targetCount - countTools())
for i = 1, maxRequests do
    if _G.StopImageToolLoops then break end
    local ok, response = pcall(function()
        return remote:InvokeServer("PickingTools", imageText)
    end)
    if not ok or response == false then
        warn("Tool request rejected:", response)
        break
    end
    requested += 1
    task.wait(0.01) -- small yield to avoid flooding the server
end
print("Requested:", requested, "Tools observed:", countTools())

-- Stop the loops by setting _G.StopImageToolLoops = true
_G.StopImageToolLoops = false
local Players = game:GetService("Players")
local player = Players.LocalPlayer

task.spawn(function()
    while not _G.StopImageToolLoops do
        local char = player.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            for _, other in ipairs(Players:GetPlayers()) do
                if _G.StopImageToolLoops then break end
                if other ~= player then
                    local target = other.Character and other.Character:FindFirstChild("HumanoidRootPart")
                    if target then
                        root.CFrame = target.CFrame * CFrame.new(0, 0, 3)
                        task.wait(0.001)
                    end
                end
            end
        end
        task.wait(0.001)
    end
end)
